Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v6.json",
  "description": "¿Cómo va cada país frente a las referencias? Todas las líneas van en gris y dos se ven siempre: Online (azul) y Estados Unidos (naranja). Por CSalcedoDataBI · https://csalcedodatabi.com/deneb/benchmark-ventas-por-pais",
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": {
    "top": 4,
    "right": 88,
    "bottom": 0,
    "left": 4
  },
  "title": {
    "text": "Ventas — comparativa por país",
    "subtitle": "Online y Estados Unidos resaltados · haz clic en un punto para resaltar su país",
    "anchor": "start",
    "fontSize": 10,
    "subtitleFontSize": 9,
    "color": "#8A8F98",
    "subtitleColor": "#6B7280",
    "offset": 6
  },
  "transform": [
    {
      "filter": "isValid(datum[''Sales Amount''])"
    },
    {
      "window": [
        {
          "op": "dense_rank",
          "as": "rk"
        }
      ],
      "sort": [
        {
          "field": "Month Date",
          "order": "descending"
        }
      ]
    },
    {
      "filter": "datum.rk <= 24"
    },
    {
      "calculate": "timeFormat(datum[''Month Date''], \"%b ''%y\")",
      "as": "label"
    },
    {
      "calculate": "pbiFormat(datum[''Sales Amount''], (isValid(datum[''Sales Amount__format'']) ? datum[''Sales Amount__format''] : ''$ #,0''), {value: (abs(datum[''Sales Amount''])>=1e9?1e9:abs(datum[''Sales Amount''])>=1e6?1e6:abs(datum[''Sales Amount''])>=1e3?1e3:1), precision: (abs(datum[''Sales Amount''])/(abs(datum[''Sales Amount''])>=1e9?1e9:abs(datum[''Sales Amount''])>=1e6?1e6:abs(datum[''Sales Amount''])>=1e3?1e3:1) >= 100 || abs(datum[''Sales Amount''])/(abs(datum[''Sales Amount''])>=1e9?1e9:abs(datum[''Sales Amount''])>=1e6?1e6:abs(datum[''Sales Amount''])>=1e3?1e3:1) == round(abs(datum[''Sales Amount''])/(abs(datum[''Sales Amount''])>=1e9?1e9:abs(datum[''Sales Amount''])>=1e6?1e6:abs(datum[''Sales Amount''])>=1e3?1e3:1))) ? 0 : 1})",
      "as": "valueLabel"
    },
    {
      "calculate": "datum.__selected__ === ''on'' ? 1 : 0",
      "as": "sel"
    },
    {
      "joinaggregate": [
        {
          "op": "max",
          "field": "sel",
          "as": "countrySel"
        }
      ],
      "groupby": [
        "Country"
      ]
    },
    {
      "calculate": "datum[''Country''] === ''Online'' || datum[''Country''] === ''United States'' || datum.countrySel === 1",
      "as": "hi"
    },
    {
      "as": "hiColor",
      "calculate": "datum[''Country''] === ''Online'' ? ''#1F4E79'' : datum[''Country''] === ''United States'' ? ''#E07A1F'' : ''#2E8B57''"
    }
  ],
  "encoding": {
    "x": {
      "field": "label",
      "type": "ordinal",
      "sort": {
        "field": "Month Date",
        "op": "min"
      },
      "axis": {
        "title": null,
        "labelAngle": 0,
        "labelOverlap": true,
        "domainColor": "#8A8F98",
        "ticks": false
      }
    },
    "y": {
      "field": "Sales Amount",
      "type": "quantitative",
      "axis": {
        "title": null,
        "domain": false,
        "ticks": false,
        "gridColor": "#EEEEEE",
        "tickCount": 5,
        "labelExpr": "pbiFormat(datum.value, ''$ #,0'', {value: (abs(datum.value)>=1e9?1e9:abs(datum.value)>=1e6?1e6:abs(datum.value)>=1e3?1e3:1), precision: (abs(datum.value)/(abs(datum.value)>=1e9?1e9:abs(datum.value)>=1e6?1e6:abs(datum.value)>=1e3?1e3:1) >= 100 || abs(datum.value)/(abs(datum.value)>=1e9?1e9:abs(datum.value)>=1e6?1e6:abs(datum.value)>=1e3?1e3:1) == round(abs(datum.value)/(abs(datum.value)>=1e9?1e9:abs(datum.value)>=1e6?1e6:abs(datum.value)>=1e3?1e3:1))) ? 0 : 1})",
        "labelFlush": true
      }
    }
  },
  "layer": [
    {
      "name": "BenchLineGray",
      "transform": [
        {
          "filter": "!datum.hi"
        }
      ],
      "mark": {
        "type": "line",
        "strokeWidth": 1.25,
        "color": "#D5D8DC",
        "interpolate": "linear"
      },
      "encoding": {
        "detail": {
          "field": "Country"
        }
      }
    },
    {
      "name": "BenchLine",
      "transform": [
        {
          "filter": "datum.hi"
        }
      ],
      "mark": {
        "type": "line",
        "strokeWidth": 2.5,
        "interpolate": "linear"
      },
      "encoding": {
        "color": {
          "scale": null,
          "field": "hiColor",
          "type": "nominal",
          "legend": null
        }
      }
    },
    {
      "name": "BenchPointGray",
      "transform": [
        {
          "filter": "!datum.hi"
        }
      ],
      "mark": {
        "type": "point",
        "filled": true,
        "size": 30,
        "color": "#C4C9CE",
        "tooltip": true
      },
      "encoding": {
        "tooltip": [
          {
            "field": "label",
            "title": "Mes"
          },
          {
            "field": "Country",
            "title": "País"
          },
          {
            "field": "valueLabel",
            "title": "Ventas"
          }
        ]
      }
    },
    {
      "name": "BenchPoint",
      "transform": [
        {
          "filter": "datum.hi"
        }
      ],
      "mark": {
        "type": "point",
        "filled": true,
        "size": 40,
        "tooltip": true
      },
      "encoding": {
        "color": {
          "scale": null,
          "field": "hiColor",
          "type": "nominal",
          "legend": null
        },
        "tooltip": [
          {
            "field": "label",
            "title": "Mes"
          },
          {
            "field": "Country",
            "title": "País"
          },
          {
            "field": "valueLabel",
            "title": "Ventas"
          }
        ]
      }
    },
    {
      "name": "BenchEndLabel",
      "transform": [
        {
          "filter": "datum.hi && datum.rk === 1"
        },
        {
          "calculate": "[datum[''Country''], datum.valueLabel]",
          "as": "endLabel"
        }
      ],
      "mark": {
        "type": "text",
        "align": "left",
        "dx": 6,
        "fontSize": 10,
        "fontWeight": "bold"
      },
      "encoding": {
        "text": {
          "field": "endLabel"
        },
        "color": {
          "scale": null,
          "field": "hiColor",
          "type": "nominal",
          "legend": null
        }
      }
    }
  ]
}'
